Command `cd /workspace/repo-vul/src-vul/gpac && python3 - <<'PY'
import os,re
for root,dirs,files in os.walk('src'):
 if '/.' in root: continue
 for fn in files:
  if not fn.endswith('.c'): continue
  path=os.path.join(root,fn)
  try: txt=open(path,errors='ignore').read().splitlines()
  except: continue
  locals=set()
  for i,l in enumerate(txt,1):
   # local decl rough inside funcs: type name; or type name =
   m=re.match(r'\s*(?:GF_\w+|u\d+|s\d+|Bool|char|int|u64|s64|u32|s32|u16|s16|u8|s8|Double|Float)\s+([A-Za-z_]\w*)\s*(?:[;=,\[])', l)
   if m: locals.add(m.group(1))
   for name in list(locals):
    if '&'+name in l and not re.search(r'\b(?:memset|sizeof|printf|LOG|assert|return)\b', l):
     if re.search(r'(->|\.)\w+\s*=\s*&'+name, l) or re.search(r'gf_list_add|gf_list_insert|gf_bs_new|set_|add_', l):
      print(f'{path}:{i}:{l.strip()}')
